#ifndef MINIMAP_MARKS_GLSL
#define MINIMAP_MARKS_GLSL

// Recognizing map faces. Needs nothing else, so Sodium's terrain shader can include it too.

// The heights of map faces, in 1/64 of a block (quarter model pixels): bit n set for n / 64.
// The same as MARKS in map_faces.py.
const uint MAP_MARKS_LOW = 0x2a002aa8u;    // n = 0..31
const uint MAP_MARKS_HIGH = 0x2aa800a8u;   // n = 32..63

// Whether a model coordinate (in blocks) is at one of the map-face heights.
bool isMark(float coordinate) {
    float q = fract(coordinate) * 64.0;
    float n = round(q);
    if (abs(q - n) > 0.01) {
        return false;
    }
    uint bit = uint(n);
    return bit < 32u ? ((MAP_MARKS_LOW >> bit) & 1u) != 0u : ((MAP_MARKS_HIGH >> (bit - 32u)) & 1u) != 0u;
}

#endif

#ifndef MINIMAP_LAYOUT_GLSL
#define MINIMAP_LAYOUT_GLSL

// The map's place on screen, in normalized device coordinates, from the aspect ratio alone: Sodium's
// terrain shader has no screen size. aspect = screen height / width, which is also
// ProjMat[0][0] / ProjMat[1][1]. Needs nothing else, so Sodium's shaders can include it.

const int MAP_BLOCKS = 128;             // blocks across the capture square
const int MAP_RADIUS = 64;              // radius of the round map, in blocks
const float MAP_RADIUS_NDC = 0.25;      // radius of the round map: a quarter of the screen height across
const float MAP_MARGIN_NDC = 0.04;      // between the map and the corner of the screen
const float MAP_CAPTURE_NDC = MAP_RADIUS_NDC * 1.38;   // side of the capture square, inside the disc
const float MAP_TAG = 0.5;              // alpha of map texels in minecraft:main
const float MAP_HEADING_TAG = 0.25;     // alpha of the capture texels that carry the heading

vec2 mapCenterNdc(float aspect) {
    return vec2(1.0 - (MAP_MARGIN_NDC + MAP_RADIUS_NDC) * aspect, 1.0 - MAP_MARGIN_NDC - MAP_RADIUS_NDC);
}

vec2 mapBlockNdc(float aspect) {
    return vec2(aspect, 1.0) * (MAP_CAPTURE_NDC / float(MAP_BLOCKS));
}

// A point of the capture, from its x and z relative to the camera's block. North up.
vec2 captureNdc(vec2 rel, float aspect) {
    return mapCenterNdc(aspect) + vec2(rel.x, -rel.y) * mapBlockNdc(aspect);
}

bool inCapture(vec2 ndc, float aspect) {
    vec2 d = abs(ndc - mapCenterNdc(aspect)) / mapBlockNdc(aspect);
    return all(lessThan(d, vec2(float(MAP_BLOCKS / 2))));
}

// The block of the capture under a point, relative to the camera's block.
ivec2 captureBlock(vec2 ndc, float aspect) {
    vec2 d = (ndc - mapCenterNdc(aspect)) / mapBlockNdc(aspect);
    return ivec2(floor(vec2(d.x, -d.y)));
}

// Depth of a map face: higher blocks in front (depth is reversed).
float mapDepth(float relY) {
    return 0.5 + 0.4 * clamp(relY / 512.0, -1.0, 1.0);
}

// The color of a block on the map: the sprite's average (mip level 4 of a 16x16 sprite) times the
// vertex color (tint and ambient occlusion), tinted by the depth of water above, which the sky light
// of the face tells: one level less per block of water.
vec3 mapColor(vec4 texel, vec3 vertexColor, float skyLight) {
    vec3 color = texel.rgb * vertexColor;
    float depth = 15.0 - skyLight;
    if (depth > 0.5) {
        color = mix(color, vec3(0.17, 0.32, 0.66), clamp(0.55 + depth * 0.03, 0.0, 0.9));
    }
    return color;
}

// The heading, in turns clockwise from north, as 24 bits in RGB: from the camera's right vector, a
// quarter turn back.
vec3 packHeading(mat4 modelView) {
    vec3 right = vec3(modelView[0][0], modelView[1][0], modelView[2][0]);
    uint v = uint(fract(atan(right.z, right.x) / 6.2831853) * 16777216.0);
    return vec3(float(v >> 16u), float((v >> 8u) & 255u), float(v & 255u)) / 255.0;
}

float unpackHeading(vec3 rgb) {
    uvec3 b = uvec3(round(rgb * 255.0));
    return float((b.r << 16u) | (b.g << 8u) | b.b) / 16777216.0;
}

#endif

#ifndef MINIMAP_GLSL
#define MINIMAP_GLSL

#include <minimap:marks.glsl>
#include <minimap:layout.glsl>

// For the post effect, which has the screen size and the camera's block. Needs Globals.

const int MAP_MEMORY = 256;   // blocks across the memory (a power of two); its row 256 keeps the heading

float screenAspect() {
    return ScreenSize.y / ScreenSize.x;
}

// The pixel at the center of a block of the capture. With less than a pixel per block (a small window),
// neighbors can share it.
ivec2 capturePixel(ivec2 rel) {
    vec2 ndc = captureNdc(vec2(rel) + 0.5, screenAspect());
    return ivec2(floor((ndc * 0.5 + 0.5) * ScreenSize));
}

ivec2 memoryTexel(ivec2 world) {
    return world & (MAP_MEMORY - 1);
}

float memoryRegion(ivec2 world) {
    ivec2 region = (world >> 8) & 7;
    return float(1 + region.x + 8 * region.y) / 255.0;
}

#endif

